#include "conv_depthwise2d_asymmetric_input_asymmetric_kernel_custom_tiling.h"
#include "register/op_def_registry.h"
#include "tiling/tiling_api.h"

namespace {
inline uint32_t CeilDiv(uint32_t a, uint32_t b) {
    return (a + b - 1) / b;
}
inline uint32_t ComputeOut(uint32_t in, uint32_t k, uint32_t s, uint32_t p, uint32_t d) {
    // out = floor((in + 2*pad - d*(k-1) - 1)/stride + 1)
    int64_t num = static_cast<int64_t>(in) + 2 * static_cast<int64_t>(p) - static_cast<int64_t>(d) * (static_cast<int64_t>(k) - 1) - 1;
    if (num < 0) num = 0;
    return static_cast<uint32_t>(num / static_cast<int64_t>(s) + 1);
}
}

namespace optiling {
static ge::graphStatus TilingFunc(gert::TilingContext *context)
{
    ConvDepthwise2dAsymmetricInputAsymmetricKernelCustomTiling tiling;

    // Fetch input shapes
    const gert::Shape *xShape = context->GetInputShape(0);
    const gert::Shape *wShape = context->GetInputShape(1);

    // Assume ND with NCHW for x: [N, C, H, W], weight: [C, 1, KH, KW]
    // Fallback to OriginShape if needed
    uint32_t n = (uint32_t)xShape->GetDim(0);
    uint32_t c = (uint32_t)xShape->GetDim(1);
    uint32_t h = (uint32_t)xShape->GetDim(2);
    uint32_t w = (uint32_t)xShape->GetDim(3);

    uint32_t kh = (uint32_t)wShape->GetDim(2);
    uint32_t kw = (uint32_t)wShape->GetDim(3);

    // Read attributes from RuntimeAttrs if provided, else default to 1/0
    const gert::RuntimeAttrs *attrs = context->GetAttrs();
    uint32_t stride_h = 1, stride_w = 1, pad_h = 0, pad_w = 0, dil_h = 1, dil_w = 1, has_bias = 0;

    if (attrs && attrs->GetNumAttrs() >= 7) {
        stride_h = *(attrs->GetAttrPointer<uint32_t>(0));
        stride_w = *(attrs->GetAttrPointer<uint32_t>(1));
        pad_h    = *(attrs->GetAttrPointer<uint32_t>(2));
        pad_w    = *(attrs->GetAttrPointer<uint32_t>(3));
        dil_h    = *(attrs->GetAttrPointer<uint32_t>(4));
        dil_w    = *(attrs->GetAttrPointer<uint32_t>(5));
        has_bias = *(attrs->GetAttrPointer<uint32_t>(6));
    }

    uint32_t out_h = ComputeOut(h, kh, stride_h, pad_h, dil_h);
    uint32_t out_w = ComputeOut(w, kw, stride_w, pad_w, dil_w);

    // Simple channel partition among blocks
    const uint32_t blockdim = 8;
    context->SetBlockDim(blockdim);
    uint32_t channelPerBlock = CeilDiv(c, blockdim);

    tiling.set_n(n);
    tiling.set_c(c);
    tiling.set_h(h);
    tiling.set_w(w);
    tiling.set_kh(kh);
    tiling.set_kw(kw);
    tiling.set_stride_h(stride_h);
    tiling.set_stride_w(stride_w);
    tiling.set_pad_h(pad_h);
    tiling.set_pad_w(pad_w);
    tiling.set_dil_h(dil_h);
    tiling.set_dil_w(dil_w);
    tiling.set_out_h(out_h);
    tiling.set_out_w(out_w);
    tiling.set_has_bias(has_bias);
    tiling.set_channelPerBlock(channelPerBlock);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // No workspace
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;

    return ge::GRAPH_SUCCESS;
}
